 59	    public static function doUpdateModuleDocumentation() : void
 60	    {
 61	        echo '- Updating module documentation...'.PHP_EOL;
 62	
 63	        $rootFolder = FolderInfo::factory(__DIR__.'/../../../../');
 64	
 65	        (new ModulesOverviewGenerator($rootFolder))->generate();
 66	
 67	        $glossaryOutputPath = rtrim($rootFolder->getPath(), '/').'/docs/agents/project-manifest/module-glossary.md';
